// Checks that Convex sent this event. Convex signs `${timestamp}.${body}` with
// HMAC-SHA256 and CONVEX_TO_N8N_SECRET, an environment variable on this n8n server.
// The webhook hands over the parsed JSON body. JSON.stringify gives back exactly
// the string Convex signed, because Convex built that string with JSON.stringify.
const crypto = require('crypto');

const secret = $env.CONVEX_TO_N8N_SECRET;
if (!secret) throw new Error('CONVEX_TO_N8N_SECRET is not set on the n8n server');

const { headers = {}, body = {} } = $input.first().json;
const timestamp = String(headers['x-lendloop-timestamp'] ?? '');
const signature = String(headers['x-lendloop-signature'] ?? '');

function problem() {
  if (!/^\d+$/.test(timestamp)) return 'missing timestamp';
  if (Math.abs(Date.now() - Number(timestamp)) > 5 * 60 * 1000) return 'timestamp older than 5 minutes';
  if (!/^[0-9a-f]{64}$/i.test(signature)) return 'missing signature';
  const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${JSON.stringify(body)}`).digest();
  return crypto.timingSafeEqual(expected, Buffer.from(signature, 'hex')) ? null : 'signature mismatch';
}

const reason = problem();
return [{ json: reason ? { valid: false, reason } : { valid: true, ...body } }];

// Writes the message from the minimal payload Convex sends: the recipient's first
// name and email, the tool name and the loan dates. Nothing else about either
// person reaches n8n.
const { eventId, type, requestId, recipient, tool, loan } = $json;
const hi = `Hi ${recipient.name},`;
const dates = `${loan.startDate} to ${loan.endDate}`;

const messages = {
  'request.created': {
    subject: `New request to borrow your ${tool.name}`,
    text: `${hi} a neighbor would like to borrow your ${tool.name} from ${dates}. Open LendLoop to approve or decline it.`,
    activity: 'Lender notified of the new request',
  },
  'request.cancelled': {
    subject: `Request for your ${tool.name} cancelled`,
    text: `${hi} the request to borrow your ${tool.name} from ${dates} was cancelled. You don't need to do anything.`,
    activity: 'Lender notified of the cancellation',
  },
  'request.approved': {
    subject: `Approved: ${tool.name}`,
    text: `${hi} your request to borrow the ${tool.name} from ${dates} was approved. Arrange the pickup with the lender on LendLoop.`,
    activity: 'Borrower notified of the approval',
  },
  'request.declined': {
    subject: `Declined: ${tool.name}`,
    text: `${hi} your request to borrow the ${tool.name} from ${dates} was declined.${loan.declineReason ? ` Reason: ${loan.declineReason}` : ''}`,
    activity: 'Borrower notified of the decline',
  },
  'loan.borrowed': {
    subject: `You have the ${tool.name}`,
    text: `${hi} enjoy the ${tool.name}. Please return it by ${loan.dueDate}.`,
    activity: 'Borrower reminded of the due date',
  },
  'loan.returned': {
    subject: `Thanks for returning the ${tool.name}`,
    text: `${hi} the lender marked the ${tool.name} as returned. Thanks for borrowing on LendLoop.`,
    activity: 'Borrower sent the return confirmation',
  },
};

const message = messages[type];
if (!message) throw new Error(`Unknown LendLoop event type: ${type}`);
return { json: { eventId, requestId, type, to: recipient.email, ...message } };

// Reports the notification to LendLoop, where it shows on the loan. Reads the
// message from "Compose message", because $json here is Resend's response.
// The key comes from the Convex event id, so a retried or duplicated delivery
// updates the same log entry instead of adding one. Signed with N8N_TO_CONVEX_SECRET.
const crypto = require('crypto');

const secret = $env.N8N_TO_CONVEX_SECRET;
if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set on the n8n server');

const message = $('Compose message').item.json;
const body = JSON.stringify({
  idempotencyKey: `notify:${message.eventId}`,
  borrowRequestId: message.requestId,
  type: 'notification',
  status: 'sent',
  message: message.activity,
});
const timestamp = String(Date.now());
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
return { json: { body, timestamp, signature } };
